import * as React from 'react';
import { Button, Divider, DropEvent, DropdownGroup, DropdownItem, DropdownList, Icon } from '@patternfly/react-core';
import {
  CloseIcon,
  ExpandIcon,
  FingerprintIcon,
  OpenDrawerRightIcon,
  OutlinedWindowRestoreIcon,
} from '@patternfly/react-icons';
import {
  Chatbot,
  ChatbotAlert,
  ChatbotContent,
  ChatbotConversationHistoryNav,
  ChatbotDisplayMode,
  ChatbotFooter,
  ChatbotFootnote,
  ChatbotHeader,
  ChatbotHeaderActions,
  ChatbotHeaderMain,
  ChatbotHeaderMenu,
  ChatbotHeaderOptionsDropdown,
  ChatbotHeaderTitle,
  ChatbotWelcomePrompt,
  Conversation,
  FileDetailsLabel,
  FileDropZone,
  Message,
  MessageBar,
  MessageBox,
  MessageProps,
  TermsOfUse,
} from '@patternfly/chatbot';
import PatternFlyAvatar from '@app/bgimages/patternfly_avatar.svg';
import UserAvatar from '@app/bgimages/user_avatar.svg';

interface ChatbotLayoutProps {
  conversations: { [key: string]: Conversation[] };
  messages: MessageProps[];
  setMessages: (messages: any) => void;
  isOpen: boolean;
  setIsOpen: (bool: boolean) => void;
}

const footnoteProps = {
  label: 'Bot uses AI. Check for mistakes.',
  popover: {
    title: 'Verify accuracy',
    description: `While Bot strives for accuracy, there's always a possibility of errors. It's a good practice to verify critical information from reliable sources, especially if it's crucial for decision-making or actions.`,
    bannerImage: {
      src: 'https://cdn.dribbble.com/userupload/10651749/file/original-8a07b8e39d9e8bf002358c66fce1223e.gif',
      alt: 'Example image for footnote popover',
    },
  },
};

const quickResponseOneContent = `If you believe that you've come across a PatternFly bug, alert our team, so that we can resolve the issue. To report a bug, follow these steps:

1. View the documentation for the feature, to confirm that the behavior is not functioning as intended.
2. Search open issues in the patternfly and patternfly-react repositories to see if a related issue already exists.
If the bug is present in only the React implementation of PatternFly, create a bug issue in patternfly-react.
If the bug can be seen on both the React and HTML/CSS side, create a bug issue in patternfly.
3. Be sure to mention which project the bug was noticed in and if there is a deadline that the fix is needed for.
`;

const quickResponseThreeContent = `Design tokens are variables that store visual design attributes like color,  typography, and spacing. Tokens have a name and value that conveys their associated design style, making their purpose clear and recognizable.
PatternFly's tokens are set up as variables and styles within Figma, and are  available as CSS variables for development. Tokens are only available as part of the PatternFly 6 release, so make sure you [upgrade to PatternFly 6](https://www.patternfly.org/get-started/upgrade/) and/or [install our Figma library](https://www.patternfly.org/get-started/design/#figma-library) in order to take advantage of tokens. PatternFly 6 components, charts, and extensions are all built with tokens.`;

const ChatbotLayout: React.FunctionComponent<ChatbotLayoutProps> = ({
  conversations,
  messages,
  setMessages,
  isOpen,
  setIsOpen,
}) => {
  const [displayMode, setDisplayMode] = React.useState(ChatbotDisplayMode.default);
  const [isDrawerOpen, setIsDrawerOpen] = React.useState(false);
  const [announcement, setAnnouncement] = React.useState<string>();
  const [showWelcomePrompts, setShowWelcomePrompts] = React.useState(true);
  const [error, setError] = React.useState<string>();
  const [file, setFile] = React.useState<File>();
  const [isLoadingFile, setIsLoadingFile] = React.useState<boolean>(false);
  const [filteredConversations, setFilteredConversations] = React.useState<{ [key: string]: Conversation[] }>(
    conversations,
  );
  const [showTermsOfUse, setShowTermsOfUse] = React.useState(false);
  const [value, setValue] = React.useState('');
  const scrollToBottomRef = React.useRef<HTMLDivElement>(null);
  const chatbotRef = React.useRef<HTMLDivElement>(null);
  const historyRef = React.useRef<HTMLButtonElement>(null);

  React.useEffect(() => {
    const newConversations: { [key: string]: Conversation[] } = findMatchingItems(value);
    setFilteredConversations(newConversations);
  }, [conversations]);

  const setConversation = (id) => {
    setShowWelcomePrompts(false);

    const matchingConvo = Object.entries(conversations).flatMap(([key, conversations]) =>
      conversations.filter((conversation) => conversation.id === id).map((conversation) => ({ key, conversation })),
    )[0];

    const getMatchingConvoDate = () => {
      const year = new Date().getFullYear();
      const month = new Date().getMonth() + 1;
      switch (matchingConvo.key) {
        case 'This month':
          return new Date(`${month} 1 ${year}`);
        case 'March':
          return new Date(`March 1 ${year}`);
        case 'February':
          return new Date(`February 1 ${year}`);
        case 'January':
          return new Date(`January 1 ${year}`);
        default:
          return new Date();
      }
    };
    const date = getMatchingConvoDate();
    const newMessage = {
      id: generateId(),
      role: 'user',
      avatar: UserAvatar,
      content: matchingConvo.conversation.text,
      timestamp: date.toLocaleString(),
      avatarProps: { isBordered: true },
    };
    setMessages([newMessage]);
    scrollToBottom();
    // make announcement to assistive devices that new message has loaded
    setAnnouncement(`Message from User: ${newMessage.content}`);
  };

  // you will likely want to come up with your own unique id function; this is for demo purposes only
  const generateId = () => {
    const id = Date.now() + Math.random();
    return id.toString();
  };

  const sendBotMessage = async (newBotMessage) => {
    // we can't use structuredClone since messages contains functions, but we can't mutate
    // items that are going into state or the UI won't update correctly
    const newMessages: MessageProps[] = [];
    // messages.forEach((message) => newMessages.push(message));
    newMessages.push({
      id: generateId(),
      role: 'bot',
      name: 'Bot',
      avatar: PatternFlyAvatar,
      content: '',
      isLoading: true,
    });
    // make announcement to assistive devices that new message has loaded
    setAnnouncement(`Message from Bot is loading`);
    setMessages((prevMessages: MessageProps[]) => [...prevMessages, ...newMessages]);
    await setTimeout(() => {
      setMessages((prevMessages: MessageProps[]) => {
        const newPrevMessages = [...prevMessages];
        console.log('////');
        newPrevMessages.pop();
        console.log(newPrevMessages);
        console.log(newBotMessage);
        return [...newPrevMessages, newBotMessage];
      });
      scrollToBottom();
      // make announcement to assistive devices that new message has loaded
      setAnnouncement(`Message from Bot: ${newBotMessage.content}`);
    }, 500);
  };

  const sendMessagePair = async (newUserMessage, newBotMessage) => {
    const newMessages: MessageProps[] = [];
    newMessages.push(newUserMessage);
    // make announcement to assistive devices that new message has loaded
    setAnnouncement(`Message from User: ${newUserMessage.content}`);
    newMessages.push({
      id: generateId(),
      role: 'bot',
      name: 'Bot',
      avatar: PatternFlyAvatar,
      content: '',
      isLoading: true,
    });
    // make announcement to assistive devices that new message has loaded
    setAnnouncement(`Message from Bot is loading`);
    setMessages((prevMessages: MessageProps[]) => {
      return [...prevMessages, ...newMessages];
    });
    scrollToBottom();
    await setTimeout(() => {
      setMessages((prevMessages) => {
        const newPrevMessages = [...prevMessages];
        newPrevMessages.pop();
        return [...newPrevMessages, newBotMessage];
      });
      // make announcement to assistive devices that new message has loaded
      setAnnouncement(`Message from Bot: ${newBotMessage.content}`);
      scrollToBottom();
    }, 500);
  };

  const getDate = () => {
    const date = new Date();
    return date.toLocaleString();
  };

  const onQuickResponseOneClick = async (message: string) => {
    const date = new Date();
    await sendMessagePair(
      {
        id: generateId(),
        content: message,
        role: 'user',
        avatar: UserAvatar,
        avatarProps: { isBordered: true },
        timestamp: date.toLocaleString(),
      },
      {
        id: generateId(),
        role: 'bot',
        name: 'Bot',
        avatar: PatternFlyAvatar,
        content: quickResponseOneContent,
        timestamp: date.toLocaleString(),
        actions: {
          // eslint-disable-next-line no-console
          positive: {
            onClick: () => {
              const response = {
                id: generateId(),
                content: 'Thanks for your feedback. Your response was recorded.',
                role: 'bot',
                name: 'Bot',
                avatar: PatternFlyAvatar,
                timestamp: getDate(),
              };
              sendBotMessage(response);
            },
          },
          // eslint-disable-next-line no-console
          negative: {
            onClick: () => {
              const response = {
                id: generateId(),
                content: 'Thanks for your feedback. Your response was recorded.',
                role: 'bot',
                name: 'Bot',
                avatar: PatternFlyAvatar,
                timestamp: getDate(),
              };
              sendBotMessage(response);
            },
          },
        },
      },
    );
  };

  const onQuickResponseTwoClick = async (message: string) => {
    const date = new Date();
    await sendMessagePair(
      {
        id: generateId(),
        content: message,
        role: 'user',
        avatar: UserAvatar,
        avatarProps: { isBordered: true },
        timestamp: date.toLocaleString(),
      },
      {
        id: generateId(),
        role: 'bot',
        name: 'Bot',
        avatar: PatternFlyAvatar,
        content:
          'PatternFly is an open source design system that enables designers and  developers to create consistent and usable software products.',
        sources: {
          sources: [
            {
              title: 'Getting started with PatternFly',
              link: 'https://www.patternfly.org/get-started/about-patternfly',
              body: 'At the core of PatternFly is our global community of designers, developers, and other UX professionals with a passion for open source—in other words, our Flyers.',
            },
          ],
        },
        timestamp: date.toLocaleString(),
      },
    );
  };

  const onQuickResponseThreeClick = async (message: string) => {
    const date = new Date();
    await sendMessagePair(
      {
        id: generateId(),
        content: message,
        role: 'user',
        avatar: UserAvatar,
        avatarProps: { isBordered: true },
        timestamp: date.toLocaleString(),
      },
      {
        id: generateId(),
        role: 'bot',
        name: 'Bot',
        avatar: PatternFlyAvatar,
        content: quickResponseThreeContent,
        timestamp: date.toLocaleString(),
      },
    );
  };

  const onTopicOneClick = async () => {
    const date = new Date();

    await sendMessagePair(
      {
        id: generateId(),
        content: `Learn about PatternFly
        
What is the PatternFly design system and how do I use it?`,
        role: 'user',
        avatar: UserAvatar,
        avatarProps: { isBordered: true },
        timestamp: date.toLocaleString(),
      },
      {
        id: generateId(),
        content: 'Sure! I can help with your questions about PatternFly. What information do you need?',
        role: 'bot',
        name: 'Bot',
        avatar: PatternFlyAvatar,
        quickResponses: [
          {
            id: '1',
            content: 'How do I report a bug?',
            onClick: () => onQuickResponseOneClick('How do I report a bug?'),
          },
          { id: '2', content: 'What is PatternFly?', onClick: () => onQuickResponseTwoClick('What is PatternFly?') },
          {
            id: '3',
            content: 'What are design tokens?',
            onClick: () => onQuickResponseThreeClick('What are design tokens?'),
          },
        ],
        timestamp: date.toLocaleString(),
      },
    );
    setShowWelcomePrompts(false);
  };

  const welcomePrompts = [
    {
      title: 'Learn about PatternFly',
      message: 'What is the PatternFly design system and how do I use it?',
      onClick: onTopicOneClick,
    },
  ];

  const findMatchingItems = (targetValue: string) => {
    let filteredConversations = Object.entries(conversations).reduce((acc, [key, items]) => {
      const filteredItems = items.filter((item) => item.text.toLowerCase().includes(targetValue.toLowerCase()));
      if (filteredItems.length > 0) {
        acc[key] = filteredItems;
      }
      return acc;
    }, {});

    // append message if no items are found
    if (Object.keys(filteredConversations).length === 0) {
      filteredConversations = [{ id: '-1', noIcon: true, text: 'No results found' }];
    }
    return filteredConversations;
  };

  React.useEffect(() => {
    scrollToBottom();
  }, [messages]);

  const scrollToBottom = () => {
    scrollToBottomRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  const handleSend = async (message: string) => {
    setShowWelcomePrompts(false);
    const lowerCaseMsg = message.toLowerCase();
    switch (lowerCaseMsg) {
      case 'how do i report a bug?':
      case 'how do i report a bug':
        onQuickResponseOneClick(message);
        break;
      case 'what is patternfly?':
      case 'what is patternfly':
        onQuickResponseTwoClick(message);
        break;
      case 'what are design tokens?':
      case 'what are design tokens':
        onQuickResponseThreeClick(message);
        break;
      default:
        await sendMessagePair(
          {
            id: generateId(),
            role: 'user',
            avatar: UserAvatar,
            avatarProps: { isBordered: true },
            content: message,
            attachments: file ? [file] : undefined,
            timestamp: getDate(),
          },
          {
            id: generateId(),
            role: 'bot',
            name: 'Bot',
            avatar: PatternFlyAvatar,
            content: 'This is beyond my knowledge base. Try asking something else.',
            timestamp: getDate(),
          },
        );
        if (file) {
          setFile(undefined);
        }
        if (file) {
          setFile(undefined);
        }
    }
    scrollToBottom();
  };

  const onSelectMenuItem = (
    _event: React.MouseEvent<Element, MouseEvent> | undefined,
    value: string | number | undefined,
  ) => {
    if (value === 'Terms of use') {
      setShowTermsOfUse(true);
    } else {
      setDisplayMode(value as ChatbotDisplayMode);
    }
  };

  // handle file drop/selection
  const handleFile = (fileArr: File[]) => {
    setIsLoadingFile(true);
    // any custom validation you may want
    if (fileArr.length > 1) {
      setFile(undefined);
      setError('Uploaded more than one file.');
      return;
    }
    // this is 25MB in bytes; size is in bytes
    if (fileArr[0].size > 25000000) {
      setFile(undefined);
      setError('File is larger than 25MB.');
      return;
    }

    setFile(fileArr[0]);
    setError(undefined);
    // this is just for demo purposes, to make the loading state really obvious
    setTimeout(() => {
      setIsLoadingFile(false);
    }, 1000);
  };

  const handleFileDrop = (event: DropEvent, data: File[]) => {
    handleFile(data);
  };

  const handleAttach = (data: File[]) => {
    handleFile(data);
  };

  const onClose = () => {
    setFile(undefined);
  };

  const introduction = (
    <>
      <p>
        Welcome to PatternFly! These terms and conditions outline the rules and regulations for the use of
        PatternFly&apos;s website, located at <a href="https://patternfly.org">www.patternfly.org.</a>
      </p>
      <p>
        By accessing this website, you are agreeing with our terms and conditions. If you do not agree to all of these
        terms and conditions, do not continue to use PatternFly.
      </p>
    </>
  );

  const terminology = (
    <>
      <p>
        The following terminology applies to these Terms and Conditions, Privacy Statement, Disclaimer Notice, and all
        Agreements:
      </p>
      <ul>
        <li>
          &quot;Client&quot;, &quot;You&quot;, and &quot;Your&quot; refer to you, the person using this website who is
          compliant with the Company&apos;s terms and conditions.
        </li>
        <li>
          &quot;The Company&quot;, &quot;Ourselves&quot;, &quot;We&quot;, &quot;Our&quot;, and &quot;Us&quot;, refer to
          our Company. &quot;Party&quot;, &quot;Parties&quot;, or &quot;Us&quot;, refers to both the Client and
          ourselves.
        </li>
      </ul>
    </>
  );

  const body = (
    <>
      <h2>Introduction</h2>
      {introduction}
      <h2>Terminology</h2>
      {terminology}
    </>
  );

  return (
    <>
      <Chatbot displayMode={displayMode} ref={chatbotRef} isVisible={isOpen}>
        <ChatbotConversationHistoryNav
          displayMode={displayMode}
          onDrawerToggle={() => {
            setIsDrawerOpen(!isDrawerOpen);
            setFilteredConversations(conversations);
          }}
          isDrawerOpen={isDrawerOpen}
          setIsDrawerOpen={setIsDrawerOpen}
          // eslint-disable-next-line no-console
          onSelectActiveItem={(e, selectedItem) => setConversation(selectedItem)}
          conversations={filteredConversations}
          onNewChat={() => {
            setIsDrawerOpen(!isDrawerOpen);
            setMessages([]);
            setFilteredConversations(conversations);
            setShowWelcomePrompts(true);
          }}
          handleTextInputChange={(value: string) => {
            if (value === '') {
              setFilteredConversations(conversations);
            }
            setValue(value);
            // this is where you would perform search on the items in the drawer
            // and update the state
            const newConversations: { [key: string]: Conversation[] } = findMatchingItems(value);
            setFilteredConversations(newConversations);
          }}
          drawerContent={
            <>
              <ChatbotHeader>
                <ChatbotHeaderMain>
                  <ChatbotHeaderMenu
                    ref={historyRef}
                    aria-expanded={isDrawerOpen}
                    onMenuToggle={() => setIsDrawerOpen(!isDrawerOpen)}
                  />
                  <ChatbotHeaderTitle displayMode={displayMode}></ChatbotHeaderTitle>
                </ChatbotHeaderMain>
                <ChatbotHeaderActions>
                  <ChatbotHeaderOptionsDropdown onSelect={onSelectMenuItem}>
                    <DropdownGroup label="Display mode">
                      <DropdownList>
                        <DropdownItem
                          value={ChatbotDisplayMode.default}
                          key="switchDisplayOverlay"
                          icon={<OutlinedWindowRestoreIcon aria-hidden />}
                          isSelected={displayMode === ChatbotDisplayMode.default}
                        >
                          <span>Overlay</span>
                        </DropdownItem>
                        <DropdownItem
                          value={ChatbotDisplayMode.docked}
                          key="switchDisplayDock"
                          icon={<OpenDrawerRightIcon aria-hidden />}
                          isSelected={displayMode === ChatbotDisplayMode.docked}
                        >
                          <span>Dock to window</span>
                        </DropdownItem>
                        <DropdownItem
                          value={ChatbotDisplayMode.fullscreen}
                          key="switchDisplayFullscreen"
                          icon={<ExpandIcon aria-hidden />}
                          isSelected={displayMode === ChatbotDisplayMode.fullscreen}
                        >
                          <span>Fullscreen</span>
                        </DropdownItem>
                        <Divider />
                        <DropdownItem
                          value="Terms of use"
                          key="Terms"
                          icon={
                            <Icon>
                              <FingerprintIcon />
                            </Icon>
                          }
                          isSelected={showTermsOfUse === true}
                          style={{ display: 'flex', alignItems: 'baseline' }}
                        >
                          Terms of use
                        </DropdownItem>
                      </DropdownList>
                    </DropdownGroup>
                  </ChatbotHeaderOptionsDropdown>
                  <Button
                    className="pf-chatbot__button--toggle-menu"
                    variant="plain"
                    onClick={() => setIsOpen(!isOpen)}
                    aria-label="Close ChatBot"
                    icon={
                      <Icon size="xl" isInline>
                        <CloseIcon />
                      </Icon>
                    }
                  />
                </ChatbotHeaderActions>
              </ChatbotHeader>
              <FileDropZone onFileDrop={handleFileDrop} displayMode={displayMode}>
                <ChatbotContent>
                  {/* Update the announcement prop on MessageBox whenever a new message is sent
                 so that users of assistive devices receive sufficient context  */}
                  <MessageBox position="bottom" announcement={announcement}>
                    {error && (
                      <ChatbotAlert
                        variant="danger"
                        onClose={() => {
                          setError(undefined);
                        }}
                        title="File upload failed"
                      >
                        {error}
                      </ChatbotAlert>
                    )}
                    {showWelcomePrompts && (
                      <ChatbotWelcomePrompt
                        title="Hello, Chatbot User"
                        description="How may I help you today?"
                        prompts={welcomePrompts}
                      />
                    )}
                    {/* This code block enables scrolling to the top of the last message.
                  You can instead choose to move the div with scrollToBottomRef on it below 
                  the map of messages, so that users are forced to scroll to the bottom.
                  If you are using streaming, you will want to take a different approach; 
                  see: https://github.com/patternfly/chatbot/issues/201#issuecomment-2400725173 */}
                    {messages.map((message, index) => {
                      if (index === messages.length - 1) {
                        return (
                          <>
                            <div ref={scrollToBottomRef}></div>
                            <Message key={message.id} {...message} />
                          </>
                        );
                      }
                      return <Message key={message.id} {...message} />;
                    })}
                  </MessageBox>
                </ChatbotContent>
                <ChatbotFooter>
                  {file && (
                    <div>
                      <FileDetailsLabel fileName={file.name} isLoading={isLoadingFile} onClose={onClose} />
                    </div>
                  )}
                  <MessageBar
                    onSendMessage={handleSend}
                    hasMicrophoneButton
                    handleAttach={handleAttach}
                    alwayShowSendButton
                  />
                  <ChatbotFootnote {...footnoteProps} />
                </ChatbotFooter>
              </FileDropZone>
            </>
          }
        ></ChatbotConversationHistoryNav>
      </Chatbot>
      {/*<ChatbotToggle
        tooltipLabel="ChatBot"
        isChatbotVisible={isOpen}
        onToggleChatbot={() => setIsOpen(!isOpen)}
        ref={toggleRef}
      />*/}
      {showTermsOfUse && (
        <TermsOfUse
          onSecondaryAction={() => setShowTermsOfUse(false)}
          isModalOpen={showTermsOfUse}
          handleModalToggle={() => setShowTermsOfUse(!showTermsOfUse)}
          displayMode={displayMode}
        >
          {body}
        </TermsOfUse>
      )}
    </>
  );
};

export { ChatbotLayout };
